import{c as r,Q as a,j as o,m as d}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"DSSA-特定领域软件架构","description":"","frontmatter":{"title":"DSSA-特定领域软件架构"},"headers":[],"relativePath":"综合知识/架构设计/特定领域软件架构.md","filePath":"综合知识/架构设计/特定领域软件架构.md","lastUpdated":null}'),e={name:"综合知识/架构设计/特定领域软件架构.md"};function s(n,t,l,h,i,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<blockquote><p>DSSA 是特定领域中<strong>一组应用的标准软件架构</strong>，三步法和四角色是高频考点。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] DSSA 定义：特定领域的标准软件架构</li><li>[ ] DSSA 三步法：领域分析 → 领域设计 → 领域实现</li><li>[ ] 四类参与角色</li><li>[ ] 垂直域 vs 水平域</li><li>[ ] 建立过程：螺旋模型</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、dssa-三步法" tabindex="-1">一、DSSA 三步法 <a class="header-anchor" href="#一、dssa-三步法" aria-label="Permalink to &quot;一、DSSA 三步法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th><th>主要活动</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong></td><td>领域模型</td><td>分析共性需求</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>DSSA</strong></td><td>领域架构</td><td>高层次设计解决方案</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织<strong>可重用信息</strong></td><td>可重用构件/资产</td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 领域设计的主要目标是<strong>获得 DSSA</strong>（不是领域模型）。建立过程是<strong>螺旋模型</strong>。</p></blockquote><h3 id="二、四类参与角色" tabindex="-1">二、四类参与角色 <a class="header-anchor" href="#二、四类参与角色" aria-label="Permalink to &quot;二、四类参与角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td><strong>领域专家</strong></td><td>提供领域知识、需求规约和实现知识</td></tr><tr><td><strong>领域分析者</strong></td><td>控制领域分析过程，组织领域模型</td></tr><tr><td><strong>领域设计者</strong></td><td>开发领域设计，验证准确性和一致性</td></tr><tr><td><strong>领域实现者</strong></td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 最适合担任领域分析师的是：<strong>具有知识工程背景的有经验的系统分析员</strong></p></blockquote><h3 id="三、垂直域-vs-水平域" tabindex="-1">三、垂直域 vs 水平域 <a class="header-anchor" href="#三、垂直域-vs-水平域" aria-label="Permalink to &quot;三、垂直域 vs 水平域&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>范围</th></tr></thead><tbody><tr><td><strong>垂直域</strong></td><td>特定的<strong>系统族</strong>，包含整个系统族内的多个系统</td><td>整个系统族</td></tr><tr><td><strong>水平域</strong></td><td>多个系统族中功能区域的<strong>共有部分</strong></td><td>子系统级</td></tr></tbody></table><h3 id="四、dssa-特征" tabindex="-1">四、DSSA 特征 <a class="header-anchor" href="#四、dssa-特征" aria-label="Permalink to &quot;四、DSSA 特征&quot;">​</a></h3><ol><li>严格定义的问题域和解决域</li><li>具有<strong>普遍性</strong></li><li>对领域有合适程度的抽象</li><li>具备固定典型开发过程中的<strong>可重用元素</strong></li></ol><blockquote><p>⚠️ &quot;随机性&quot; 不属于 DSSA 特征。</p></blockquote><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>参见 <a href="./.html">架构师-备考 综合知识-架构设计-架构风格与模式#练习题</a>（DSSA 部分 Q76-Q102），及 <a href="./.html">架构师-备考 综合知识-架构设计-架构设计方法#练习题</a>（Q25, Q42 等）</p>',17)])])}const u=r(e,[["render",s]]);export{c as __pageData,u as default};
